#include <iostream>
#include <memory>
#include <string>
using namespace std;

class Cat {
public:
    virtual string speak() const { return "……"; }
    virtual ~Cat() = default;
};

class FishCat : public Cat {
public:
    string speak() const override { return "小鱼干喵！"; }
};

class BallCat : public Cat {
public:
    string speak() const override { return "{w}喵！"; }
};

unique_ptr<Cat> makeCat(const string& kind) {
    if (kind == "{k1}") return make_unique<FishCat>();
    return make_unique<BallCat>();
}

int main() {
    auto c1 = makeCat("{k1}");
    auto c2 = makeCat("{k2}");
    cout << c1->speak() << endl;
    cout << c2->speak() << endl;
    return 0;
}
